codigo_optimizado:
/* Base mobile - siempre funciona */
body {
  font-size: clamp(14px, 2vw + 10px, 16px);
  width: 100%;
  padding-inline: 1rem;
}

/* Progresión tablet */
@media (min-width: 768px) {
  body {
    max-width: 1200px;
    margin-inline: auto;
    padding-inline: 2rem;
  }
}

/* Progresión desktop */
@media (min-width: 1200px) {
  body {
    padding-inline: 0;
  }
}

