codigo_corregido:
/* Base: estilos compartidos */
.button {
  padding: 10px;
  border-radius: 4px;
  border: none;
  cursor: pointer;
}

/* Variantes por clase, sin !important */
.button-primary {
  background-color: blue;
  color: white;
}

.button-secondary {
  background-color: red;
  color: white;
}

/* Si necesitas sobrescribir en un contexto específico, usa selectores más específicos */
.hero .button-primary {
  background-color: green;
}

codigo_optimizado:
/* Design tokens con variables CSS */
:root {
  --btn-bg-primary: #3b82f6;
  --btn-bg-secondary: #ef4444;
  --btn-text: white;
  --btn-padding: 0.75rem 1.5rem;
  --btn-radius: 0.5rem;
}

/* Una sola clase base */
.btn {
  padding: var(--btn-padding);
  border-radius: var(--btn-radius);
  border: none;
  cursor: pointer;
  color: var(--btn-text);
  font-weight: 500;
  transition: filter 0.2s;
}

/* Variantes usando composición, no herencia */
.btn--primary { background-color: var(--btn-bg-primary); }
.btn--secondary { background-color: var(--btn-bg-secondary); }
.btn:hover { filter: brightness(0.9); }

/* Si necesitas override contextual, usa variables locales */
.hero .btn--primary {
  --btn-bg-primary: #10b981;
}

simulador.estado_inicial:
.button { color: blue; }
#main .button { color: red; }
body .container .button { color: green; }
